import React from "react";
import "./HomePage.css";
import Editor from "./editor"
import { Link } from "react-router-dom";
import { Navigate } from "react-router-dom";


export default function HomePage() {
  const navigate = useNavigate();
  const logoutHandler = () => {
    localStorage.removeItem("token");  // token delete
    alert("Logged out successfully!");
    navigate("/"); // login page par redirect
  }
  return (
    <section id="homePage" className="homepage">
      <div className="hero">
        <div className="hero-text">
          <h1 className="title">
            Welcome to <span className="accent">DailyCode</span>
          </h1>

          <p className="subtitle">
            🚀 Daily Coding Challenges — Short tasks in Python, JavaScript, C++, Java and more.{" "}
            <strong>Levels:</strong> Easy / Medium / Hard
          </p>
 <button onClick={logoutHandler} style={styles.btn}>
      Logout
    </button>
          <div className="cta-row">
          
           <Link to={localStorage.getItem("token") ? "/editor" : "/login"}
  className="cta"
>
  Start Coding
</Link> 

            <a href="#" className="learn">Learn more</a>
          </div>
        </div>

        <div className="hero-image">
          <img
            src="https://media.giphy.com/media/qgQUggAC3Pfv687qPC/giphy.gif"
            alt="Developer at work"
          />
        </div>
      </div>
    </section>
  );
}
const styles={
    btn: {
    padding: "10px 20px",
    background: "red",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    fontWeight: "bold"
  }


}
